begin;
-- Additive version lineage: parent is private and must belong to the same owner/tool.
alter table public.tool_runs add column parent_run_id uuid references public.tool_runs(id) on delete set null;
alter table public.tool_runs add constraint tool_runs_parent_not_self check(parent_run_id is null or parent_run_id<>id);
create index tool_runs_parent_idx on public.tool_runs(parent_run_id);
create or replace function private.guard_tool_run() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if new.user_id is distinct from auth.uid() then raise exception 'Own account required'; end if;
 perform pg_advisory_xact_lock(hashtext('ld-tool-runs-'||new.user_id::text));
 if not exists(select 1 from public.tools t join public.tool_versions v on v.tool_id=t.id where t.id=new.tool_id and t.status='published' and v.version=new.tool_version) then raise exception 'Tool version unavailable'; end if;
 if new.parent_run_id is not null and not exists(select 1 from public.tool_runs where id=new.parent_run_id and user_id=new.user_id and tool_id=new.tool_id) then raise exception 'Own source run required'; end if;
 if (select count(*) from public.tool_runs where user_id=new.user_id)>=1000 or (select count(*) from public.tool_runs where user_id=new.user_id and completed_at>now()-interval '1 minute')>=30 then raise exception 'Private history limit'; end if;
 return new;
end $$;
revoke all on function private.guard_tool_run() from public,anon,authenticated;
create function public.save_tool_run_v2(p_id uuid,p_tool_id text,p_version integer,p_name text,p_answers jsonb,p_result jsonb,p_started_at timestamptz,p_session_id uuid,p_attribution jsonb default '{}',p_parent_id uuid default null) returns uuid language plpgsql security invoker set search_path='' as $$
declare own_id uuid=auth.uid();saved uuid;
begin
 if own_id is null then raise exception 'Sign in required'; end if;
 select id into saved from public.tool_runs where id=p_id and user_id=own_id;
 if saved is not null then return saved;end if;
 insert into public.tool_consents(user_id,purpose,privacy_version,granted) values(own_id,'private_history','tools-v1-2026-10-12',true);
 insert into public.tool_runs(id,tool_id,tool_version,user_id,session_id,name,answers,result_summary,started_at,landing_page,attribution,consent_state,parent_run_id)
 values(p_id,p_tool_id,p_version,own_id,p_session_id,p_name,p_answers,p_result,p_started_at,'/ferramentas/'||p_tool_id,p_attribution,'{"history":true,"intelligence":false,"privacy_version":"tools-v1-2026-10-12"}',p_parent_id) returning id into saved;
 return saved;
end $$;
revoke all on function public.save_tool_run_v2(uuid,text,integer,text,jsonb,jsonb,timestamptz,uuid,jsonb,uuid) from public,anon;
grant execute on function public.save_tool_run_v2(uuid,text,integer,text,jsonb,jsonb,timestamptz,uuid,jsonb,uuid) to authenticated;
-- The existing owner-only policies, immutable columns, rate limits and retention remain.
-- Catalog version updates are migrations, not impersonated admin writes. ALTER TABLE
-- locks serialize this transaction; the admin audit trigger is re-enabled before commit.
alter table public.tools disable trigger tool_admin_audit_trigger;
