insert into public.tool_versions(tool_id,version,input_schema,calculation_schema,result_schema,methodology,limitations) values('calculadora-conversao',2,'[{"id":"mode","label":"Modo de análise","type":"select","default":"simple","options":[["simple","Conversão simples"],["full","Funil completo e cenários"]]},{"id":"visits","label":"Visitas ou oportunidades","type":"number","min":1,"showWhen":{"field":"mode","value":"simple"}},{"id":"actions","label":"Ações concluídas","type":"number","min":0,"showWhen":{"field":"mode","value":"simple"}},{"id":"current_visits","label":"Atual · Visitas","type":"number","min":0,"group":"Funil atual","showWhen":{"field":"mode","value":"full"}},{"id":"current_leads","label":"Atual · Leads","type":"number","min":0,"group":"Funil atual","showWhen":{"field":"mode","value":"full"}},{"id":"current_mql","label":"Atual · MQL","type":"number","min":0,"group":"Funil atual","showWhen":{"field":"mode","value":"full"}},{"id":"current_sql","label":"Atual · SQL","type":"number","min":0,"group":"Funil atual","showWhen":{"field":"mode","value":"full"}},{"id":"current_demos","label":"Atual · Demos","type":"number","min":0,"group":"Funil atual","showWhen":{"field":"mode","value":"full"}},{"id":"current_proposals","label":"Atual · Propostas","type":"number","min":0,"group":"Funil atual","showWhen":{"field":"mode","value":"full"}},{"id":"current_sales","label":"Atual · Vendas","type":"number","min":0,"group":"Funil atual","showWhen":{"field":"mode","value":"full"}},{"id":"target_visits","label":"Meta · Visitas","type":"number","min":0,"group":"Meta (opcional)","showWhen":{"field":"mode","value":"full"}},{"id":"target_leads","label":"Meta · Leads","type":"number","min":0,"group":"Meta (opcional)","showWhen":{"field":"mode","value":"full"}},{"id":"target_mql","label":"Meta · MQL","type":"number","min":0,"group":"Meta (opcional)","showWhen":{"field":"mode","value":"full"}},{"id":"target_sql","label":"Meta · SQL","type":"number","min":0,"group":"Meta (opcional)","showWhen":{"field":"mode","value":"full"}},{"id":"target_demos","label":"Meta · Demos","type":"number","min":0,"group":"Meta (opcional)","showWhen":{"field":"mode","value":"full"}},{"id":"target_proposals","label":"Meta · Propostas","type":"number","min":0,"group":"Meta (opcional)","showWhen":{"field":"mode","value":"full"}},{"id":"target_sales","label":"Meta · Vendas","type":"number","min":0,"group":"Meta (opcional)","showWhen":{"field":"mode","value":"full"}},{"id":"alternative_visits","label":"Alternativo · Visitas","type":"number","min":0,"group":"Alternativo (opcional)","showWhen":{"field":"mode","value":"full"}},{"id":"alternative_leads","label":"Alternativo · Leads","type":"number","min":0,"group":"Alternativo (opcional)","showWhen":{"field":"mode","value":"full"}},{"id":"alternative_mql","label":"Alternativo · MQL","type":"number","min":0,"group":"Alternativo (opcional)","showWhen":{"field":"mode","value":"full"}},{"id":"alternative_sql","label":"Alternativo · SQL","type":"number","min":0,"group":"Alternativo (opcional)","showWhen":{"field":"mode","value":"full"}},{"id":"alternative_demos","label":"Alternativo · Demos","type":"number","min":0,"group":"Alternativo (opcional)","showWhen":{"field":"mode","value":"full"}},{"id":"alternative_proposals","label":"Alternativo · Propostas","type":"number","min":0,"group":"Alternativo (opcional)","showWhen":{"field":"mode","value":"full"}},{"id":"alternative_sales","label":"Alternativo · Vendas","type":"number","min":0,"group":"Alternativo (opcional)","showWhen":{"field":"mode","value":"full"}}]','{"method":"calculadora-conversao","version":2}','{"format":"structured-result-v2"}','Conversão = etapa seguinte ÷ etapa anterior × 100; perdas = etapa anterior − seguinte. Total = vendas ÷ visitas × 100. Use contagens do mesmo período e coorte, com etapas cumulativas. Denominador zero produz resultado indisponível.','Metas e cenários são premissas do usuário, não previsões. Não há taxa ideal universal. Não compare eventos