insert into public.tool_versions(tool_id,version,input_schema,calculation_schema,result_schema,methodology,limitations) values('planner-editorial',2,'[{"id":"rows","label":"Pautas","type":"rows","row_fields":[{"id":"theme","label":"Tema","type":"text"},{"id":"question","label":"Pergunta central","type":"textarea"},{"id":"thesis","label":"Tese","type":"textarea"},{"id":"persona","label":"Persona","type":"text"},{"id":"intent","label":"Intenção","type":"text"},{"id":"format","label":"Formato","type":"select","options":[["Artigo","Artigo"],["Guia","Guia"],["Post","Post"],["Vídeo","Vídeo"],["Newsletter","Newsletter"],["Shorts","Shorts"]],"default":"Artigo"},{"id":"channel","label":"Canal","type":"text","default":"Site"},{"id":"date","label":"Data","type":"date"},{"id":"status","label":"Status","type":"select","options":[["idea","Ideia"],["research","Pesquisa"],["draft","Produção"],["review","Revisão"],["scheduled","Agendado"],["published","Publicado"]],"default":"idea"},{"id":"cta","label":"CTA","type":"text"},{"id":"sources","label":"Fontes","type":"textarea"},{"id":"derivatives","label":"Derivados","type":"textarea"},{"id":"publication_url","label":"URL publicada","type":"url"}]}]','{"method":"planner-editorial","version":2}','{"format":"structured-result-v2"}','Organiza até 50 pautas informadas; lista, calendário e Kanban são visões dos mesmos dados. Alterar status não publica conteúdo no CMS.','Desempenho e receita não são estimados. URL publicada é registrada pelo usuário; marcar publicado não comprova resultados.');
